def reversePairs(nums):
    def solve(a):
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        left, cl = solve(a[:mid])
        right, cr = solve(a[mid:])
        cnt = cl + cr
        j = 0
        for x in left:
            while j < len(right) and 2 * right[j] < x:
                j += 1
            cnt += j
        return sorted(left + right), cnt
    return solve(nums)[1]
